function origin(){return(process.env.ALPHALAB_API_ORIGIN||'http://127.0.0.1:8000').replace(/\/+$/,'')}
async function get(path){const response=await fetch(origin()+path,{headers:{Accept:'application/json'}});if(!response.ok)throw new Error('AlphaLab API '+response.status+': '+await response.text());return response.json()}
function bounded(value,depth=0){if(depth>6)return'[depth limited]';if(Array.isArray(value)){if(value.length<=24)return value.map(item=>bounded(item,depth+1));return{count:value.length,head:value.slice(0,8).map(item=>bounded(item,depth+1)),tail:value.slice(-8).map(item=>bounded(item,depth+1)),truncated:true}}if(value&&typeof value==='object'){const out={};for(const [key,item] of Object.entries(value))out[key]=bounded(item,depth+1);return out}return value}
function summarizeReturns(rows){const values=Array.isArray(rows)?rows:[];return{count:values.length,start_date:values[0]?.date||null,end_date:values.at(-1)?.date||null,finite_returns:values.filter(row=>Number.isFinite(Number(row&&row.value))).length,finite_benchmark_returns:values.filter(row=>Number.isFinite(Number(row&&row.benchmark))).length}}
function summarizeWeights(rows){const values=Array.isArray(rows)?rows:[],symbols=new Set(values.map(row=>row&&row.symbol).filter(Boolean)),dates=values.map(row=>row&&row.date).filter(Boolean),lastDate=dates.length?dates.at(-1):null,last=lastDate?values.filter(row=>row&&row.date===lastDate).slice(0,30):[];return{count:values.length,symbol_count:symbols.size,start_date:dates[0]||null,end_date:lastDate,last_positions:last,last_positions_truncated:lastDate?values.filter(row=>row&&row.date===lastDate).length>last.length:false}}
function compactExecutions(rows){const values=(Array.isArray(rows)?rows:[]).map(row=>({decision_date:row?.decision_date||null,entry_date:row?.entry_date||null,activation:row?.activation||null,decision_reason:row?.decision_reason||null,target_count:row?.target_count??null,executed_count:row?.executed_count??null,total_cost:row?.total_cost??null,turnover:row?.turnover??null,state_committed:row?.state_committed??null,constrained_symbols:row?.constrained_symbols||[],missing_amount_symbols:row?.missing_amount_symbols||[],fallback_route_count:Array.isArray(row?.fallback_routes)?row.fallback_routes.length:0,executed_symbols:row?.executed_weights?Object.keys(row.executed_weights):[]}));return values.length<=120?values:{count:values.length,head:values.slice(0,40),tail:values.slice(-40),truncated:true}}
function compactBacktest(payload,includeSource=false){const out={...payload};out.returns_summary=summarizeReturns(payload.returns);out.weights_summary=summarizeWeights(payload.weights);out.execution_summary={count:Array.isArray(payload.executions)?payload.executions.length:0,rows:compactExecutions(payload.executions)};delete out.returns;delete out.weights;delete out.executions;out.attribution=bounded(payload.attribution);out.validation_output=bounded(payload.validation_output);out.provenance=bounded(payload.provenance);if(out.provenance?.strategy_python?.source&&!includeSource)out.provenance.strategy_python={sha256:out.provenance.strategy_python.sha256};const strategyAvailable=typeof payload.strategy_source==='string'||typeof payload.provenance?.strategy_python?.source==='string',validationAvailable=typeof payload.validation_source==='string';if(!includeSource){delete out.strategy_source;delete out.validation_source;if(out.strategy_snapshot?.source)delete out.strategy_snapshot.source}out.python_source_available=strategyAvailable;out.validation_source_available=validationAvailable;out.python_source_included=includeSource&&strategyAvailable;return out}
async function persisted(input){const id=String(input.backtest_id||'').trim();if(!id)throw new Error('backtest_id is required for get');return compactBacktest(await get('/api/backtests/'+encodeURIComponent(id)),input.include_python_source===true)}
async function submitBacktest(input){if(input.confirm_python_execution!==true)throw new Error('Backtest requires explicit Python execution confirmation');const id=String(input.project_id||'').trim();if(!id||!input.start_date||!input.end_date)throw new Error('project_id, start_date, and end_date are required for run');const base='/api/strategy/projects/'+encodeURIComponent(id);const [project,validation]=await Promise.all([get(base),get('/api/validation/projects/'+encodeURIComponent(id))]);if(project.dirty)throw new Error('Save the project source before running a backtest');const revision=Number(project.current_revision);const pkg=await get(base+'/revisions/'+revision);const response=await fetch(origin()+'/api/backtests/jobs',{method:'POST',headers:{Accept:'application/json','Content-Type':'application/json'},body:JSON.stringify({project_id:id,revision,start_date:String(input.start_date),end_date:String(input.end_date),profile:'runtime',confirm_python_execution:true})});if(!response.ok)throw new Error('AlphaLab API '+response.status+': '+await response.text());const job=await response.json();return{job_id:job.id,status:job.status,message:'Backtest submitted; poll with action=job until a terminal status',strategy_source_package:{project_id:id,revision,source_sha256:pkg.source_sha256},validation_source_package:{project_id:id,revision:validation.current_revision,source_sha256:validation.source_sha256}}}
async function run(input){const action=String(input.action||'');if(action==='get')return persisted(input);if(action==='job'){const id=String(input.job_id||'').trim();if(!id)throw new Error('job_id is required for job');const job=await get('/api/backtests/jobs/'+encodeURIComponent(id));if(job&&job.result)job.result=compactBacktest(job.result,false);return job}if(action==='run')return submitBacktest(input);throw new Error('unsupported backtest action')}
